"""Confere os seis arquivos de saida/ contra o formato do edital. Imprime so o que falha e um resumo do que passou."""
import csv, re, sys, collections
from decimal import Decimal as D, InvalidOperation
from pathlib import Path

RAIZ = Path(sys.argv[1])
SAIDA, INPUT = RAIZ / "saida", RAIZ / "input"
OBRIG = {
    "comissoes_por_lojista": ["id_saida", "cnpj", "lojista", "linha_negocio", "comissao_brl"],
    "divergencias_taxa": ["id_saida", "cnpj", "linha_negocio", "ref_origem", "taxa_contratada_pct", "taxa_aplicada_pct", "diferenca_brl"],
    "notas_a_emitir": ["id_saida", "tomador_cnpj", "tomador", "linha_negocio", "valor_brl", "discriminacao"],
    "lancamentos_classificados": ["id_saida", "banco", "ref_origem", "data", "descricao", "valor", "conta_codigo", "metodo", "confianca"],
    "pendencias": ["id_saida", "tipo", "ref_origem", "valor_brl", "motivo", "quem_decide"],
    "rastro": ["id_saida", "arquivo_origem", "ref_origem", "valor"],
}
NUMERICAS = {"comissao_brl", "taxa_contratada_pct", "taxa_aplicada_pct", "diferenca_brl", "valor_brl", "valor", "confianca"}
falhas, ok = [], collections.Counter()

def falha(arq, msg):
    falhas.append(f"{arq}: {msg}")

dados = {}
for nome, cols in OBRIG.items():
    caminho = SAIDA / f"{nome}.csv"
    if not caminho.exists():
        falha(nome, "ARQUIVO NAO EXISTE"); continue
    bruto = caminho.read_bytes()
    texto = bruto.decode("utf-8")                      # UTF-8 valido
    linhas = list(csv.DictReader(texto.splitlines(), delimiter=";"))
    dados[nome] = linhas
    cab = list(linhas[0].keys()) if linhas else []
    for c in cols:
        if c not in cab: falha(nome, f"coluna obrigatoria ausente: {c}")
    if "," in texto.splitlines()[0]: falha(nome, "cabecalho usa virgula (separador deve ser ;)")
    n = 0
    for i, l in enumerate(linhas, 2):
        for c in cols:
            if (l.get(c) or "").strip() == "" and not (nome == "rastro" and c == "valor"):
                falha(nome, f"linha {i}: {c} vazio"); n += 1
        for c in NUMERICAS & set(l):
            v = (l[c] or "").strip()
            if v == "": continue
            if "," in v: falha(nome, f"linha {i}: {c}={v!r} com virgula decimal"); n += 1
            else:
                try: D(v)
                except InvalidOperation: falha(nome, f"linha {i}: {c}={v!r} nao numerico"); n += 1
        for c in ("cnpj", "tomador_cnpj"):
            if c in l and not re.fullmatch(r"\d{14}", l[c] or ""): falha(nome, f"linha {i}: {c}={l[c]!r} nao tem 14 digitos"); n += 1
        if "data" in l and not re.fullmatch(r"\d{4}-\d{2}-\d{2}", l["data"] or ""): falha(nome, f"linha {i}: data={l['data']!r} fora de AAAA-MM-DD"); n += 1
        if "linha_negocio" in l and l["linha_negocio"] not in ("CHECKOUT", "REMESSA"): falha(nome, f"linha {i}: linha_negocio={l['linha_negocio']!r}"); n += 1
        if "banco" in l and l["banco"] not in ("AURORA", "MERIDIANO"): falha(nome, f"linha {i}: banco={l['banco']!r}"); n += 1
        if "metodo" in l and l["metodo"] not in ("REGRA", "IA", "HUMANO"): falha(nome, f"linha {i}: metodo={l['metodo']!r}"); n += 1
        if "confianca" in l and l["confianca"] and not (D(l["confianca"]) >= 0 and D(l["confianca"]) <= 1): falha(nome, f"linha {i}: confianca fora de 0..1"); n += 1
    ok[nome] = len(linhas)
    ids = [l["id_saida"] for l in linhas]
    if nome != "rastro":
        dup = [k for k, v in collections.Counter(ids).items() if v > 1]
        if dup: falha(nome, f"id_saida repetido: {dup[:3]}")

# rastro fecha com cada numero
if all(k in dados for k in ("rastro", "comissoes_por_lojista")):
    soma = collections.defaultdict(D)
    for r in dados["rastro"]: soma[r["id_saida"]] += D(r["valor"])
    for nome, col in (("comissoes_por_lojista", "comissao_brl"), ("divergencias_taxa", "diferenca_brl"), ("notas_a_emitir", "valor_brl"),
                      ("lancamentos_classificados", "valor"), ("pendencias", "valor_brl")):
        for l in dados.get(nome, []):
            if soma.get(l["id_saida"], D(0)) != D(l[col]): falha(nome, f"{l['id_saida']}: rastro {soma.get(l['id_saida'], D(0))} != {l[col]}")
    ids_saida = {l["id_saida"] for n in ("comissoes_por_lojista", "divergencias_taxa", "notas_a_emitir", "lancamentos_classificados", "pendencias") for l in dados.get(n, [])}
    orfaos = [i for i in soma if i not in ids_saida]
    if orfaos: falha("rastro", f"{len(orfaos)} id_saida sem numero correspondente (ex.: {orfaos[:2]})")

# ref_origem dos lancamentos: Aurora = numero da linha fisica do arquivo; Meridiano = FITID
aur = next(INPUT.glob("05a_*.csv"), None); mer = next(INPUT.glob("05b_*.ofx"), None)
if aur and "lancamentos_classificados" in dados:
    fis = aur.read_bytes().decode("cp1252", errors="replace").splitlines()
    fitids = set(re.findall(r"<FITID>(\S+)", mer.read_bytes().decode("cp1252", errors="replace"))) if mer else set()
    for l in dados["lancamentos_classificados"]:
        if l["banco"] == "AURORA":
            m = re.fullmatch(r"L(\d+)", l["ref_origem"])
            if not m: falha("lancamentos", f"{l['ref_origem']}: Aurora deve ser L<n>"); continue
            linha = fis[int(m.group(1)) - 1]
            if l["descricao"][:20].strip().lower() not in linha.lower(): falha("lancamentos", f"{l['ref_origem']}: descricao nao bate com a linha fisica ({linha[:50]!r})")
        else:
            if l["ref_origem"] not in fitids: falha("lancamentos", f"{l['ref_origem']}: FITID inexistente no OFX")
    ok["lancamentos: ref_origem conferida contra a linha fisica / FITID"] = len(dados["lancamentos_classificados"])

print("PASSOU:", dict(ok))
print(f"FALHAS: {len(falhas)}")
for f in falhas[:25]: print("  -", f)

