    for c in cols:
        if c not in cab: falha(nome, f"coluna obrigatoria ausente: {c}")
    if "," in texto.splitlines()[0]: falha(nome, "cabecalho usa virgula (separador deve ser ;)")
    n = 0
    for i, l in enumerate(linhas, 2):
        for c in cols:
            if (l.get(c) or "").strip() == "" and not (nome == "rastro" and c == "valor"):
                falha(nome, f"linha {i}: {c} vazio"); n += 1
        for c in NUMERICAS & set(l):
            v = (l[c] or "").strip()
            if v == "": continue
            if "," in v: falha(nome, f"linha {i}: {c}={v!r} com virgula decimal"); n += 1
            else:
                try: D(v)
                except InvalidOperation: falha(nome, f"linha {i}: {c}={v!r} nao numerico"); n += 1
        for c in ("cnpj", "tomador_cnpj"):
            if c in l and not re.fullmatch(r"\d{14}", l[c] or ""): falha(nome, f"linha {i}: {c}={l[c]!r} nao tem 14 digitos"); n += 1
