    ok["lancamentos: ref_origem conferida contra a linha fisica / FITID"] = len(dados["lancamentos_classificados"])

print("PASSOU:", dict(ok))
print(f"FALHAS: {len(falhas)}")
for f in falhas[:25]: print("  -", f)

